item.aggregated_output:
{
  "/api/v1/orders": {
    "get": {
      "operationId": "listOrders",
      "tags": [
        "orders"
      ],
      "parameters": [
        {
          "name": "page",
          "in": "query",
          "required": false,
          "schema": {
            "type": "integer",
            "minimum": 1
          }
        },
        {
          "name": "size",
          "in": "query",
          "required": false,
          "schema": {
            "type": "integer",
            "minimum": 1
          }
        }
      ],
      "responses": {
        "200": {
          "description": "分页订单",
          "content": {
            "application/json": {
              "schema": {
                "$ref": "#/components/schemas/OrderPageResponse"
              }
            }
          }
        },
        "401": {
          "description": "未认证",
          "content": {
            "application/json": {
              "schema": {
                "$ref": "#/components/schemas/ErrorResponse"
              }
            }
          }
        }
      }
    }
  },
  "/api/v1/orders/{orderId}/cancel": {
    "post": {
      "operationId": "cancelOrder",
      "tags": [
        "orders"
      ],
      "parameters": [
        {
          "name": "orderId",
          "in": "path",
          "required": true,
          "schema": {
            "type": "string"
          }
        }
      ],
      "requestBody": {
        "required": true,
        "content": {
          "application/json": {
            "schema": {
              "$ref": "#/components/schemas/CancelOrderRequest"
            }
          }
        }
      },
      "responses": {
        "200": {
          "description": "取消结果",
          "content": {
            "application/json": {
              "schema": {
                "$ref": "#/components/schemas/OrderResponse"
              }
            }
          }
        },
        "409": {
          "description": "订单状态冲突",
          "content": {
            "application/json": {
              "schema": {
                "$ref": "#/components/schemas/ErrorResponse"
              }
            }
          }
        }
      }
    }
  }
}
